import * as fs from 'fs'
import * as path from 'path'
import { checkTranscript } from './assertions'
import { checkTranscript as oldCheck } from './zz-old-assertions'
import * as cases from './cases'

it('regrade', () => {
  const all: any[] = Object.values(cases).flat().filter((c: any) => c && c.id)
  const out: string[] = []
  let n = 0
  for (const suite of ['full', 'smoke']) for (const tier of ['free', 'paid']) {
    const dir = path.join(__dirname, '../../../evals/agent/results', suite, tier)
    for (const f of fs.readdirSync(dir)) {
      const r = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'))
      const c = all.find((x) => x.id === r.caseId)
      r.attempts.forEach((a: any, i: number) => {
        n++
        if (!c) { out.push(`NOCASE ${r.caseId}`); return }
        const o = JSON.stringify(oldCheck(a.transcript, c).map((x: any) => x.check))
        const nw = JSON.stringify(checkTranscript(a.transcript, c).map((x: any) => x.check))
        if (o !== nw) out.push(`${suite}/${tier}/${r.caseId} #${i + 1}: ${o} -> ${nw}`)
      })
    }
  }
  console.log(n + ' attempts\n' + out.join('\n'))
})
EOF
