import type { TestingModule } from '@nestjs/testing'
import { ProfessionalProfilesRepository } from '@modules/professional-profiles/professional-profiles.repo'
import { UsersRepository } from '@modules/users/users.repo'
import { bootTestApp } from '../../testing/boot-test-app'
import { AgentConversationsRepository } from './agent-conversations.repo'
import { AgentModelClientService } from './agent-model-client.service'
import { AgentConversationService } from './agent.service'
import type { AgentModelEvent, AgentSseEvent } from './agent.types'

const ACCOUNT_ID = '507f1f77bcf86cd799439099'

describe('review probe', () => {
  let moduleRef: TestingModule
  let stop: () => Promise<void>
  let service: AgentConversationService
  let repo: AgentConversationsRepository
  let streamTurnMock: jest.SpiedFunction<AgentModelClientService['streamTurn']>

  beforeAll(async () => {
    const app = await bootTestApp()
    if (app.unavailable) throw new Error('mongo unavailable')
    moduleRef = app.moduleRef
    stop = app.stop
    streamTurnMock = jest.spyOn(moduleRef.get(AgentModelClientService), 'streamTurn')
    service = moduleRef.get(AgentConversationService)
    repo = moduleRef.get(AgentConversationsRepository)
    await moduleRef.get(UsersRepository).create({ _id: ACCOUNT_ID, email: 'p@example.com', name: 'P', status: 'active', locale: 'en' })
    await moduleRef.get(ProfessionalProfilesRepository).create({ accountId: ACCOUNT_ID, orgId: 'org-1', status: 'active', bio: '', contact: {}, coverageZips: [], affiliations: [], media: {}, services: [], active: true, chat: {} })
  })
  afterAll(async () => { await stop?.() })

  async function run(gen: () => AsyncGenerator<AgentModelEvent>) {
    streamTurnMock.mockReturnValue(gen())
    const events: AgentSseEvent[] = []
    await service.startConversation(ACCOUNT_ID, { message: 'add a section' }, (e) => events.push(e))
    const conv = await repo.findOwnedById(String(events[0]!.data.id), ACCOUNT_ID)
    return { events, assistant: conv!.messages[1]! }
  }

  it('A: read tool then cut-off edit (ticket turn 1/2 shape) is flagged truncated', async () => {
    const { events, assistant } = await run(async function* () {
      yield { type: 'tool-call', toolCallId: 'c1', toolName: 'get_journey', input: { id: 'j1' } }
      yield { type: 'tool-result', toolCallId: 'c1', toolName: 'get_journey', output: { ok: true } }
      yield { type: 'step-start' }
      yield { type: 'finish', truncated: true, usage: { inputTokens: 1, outputTokens: 6000, totalTokens: 6001 } }
    })
    console.log('A parts', JSON.stringify(assistant.parts.map((p) => p.type)), 'metadata.truncated', assistant.metadata?.truncated, 'done', JSON.stringify(events.find((e) => e.type === 'done')?.data))
    expect(assistant.metadata).toMatchObject({ truncated: true })
  })

  it('B: model error with no parts keeps metadata.error', async () => {
    const { assistant } = await run(async function* () {
      yield { type: 'error', error: 'model stream failed' }
    })
    console.log('B parts', assistant.parts.length, 'metadata', JSON.stringify({ ...assistant.metadata, telemetry: undefined }))
    expect(assistant.metadata).toMatchObject({ error: 'model stream failed' })
  })
})
EOF
